<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import { damageResult, healthPenalty, opposedResult } from '../rules/rulesEngine'
import { loreSpells } from '../data/magicOptions'
import { spellDetails } from '../data/magicDetails'
import { loadCharacters, type CharacterRecord } from '../services/characters'
import { loadEncounters, writeEncounters, type EncounterRecord } from '../services/encounters'

type StrikeType='melee'|'ranged'|'magical'
const route=useRoute(),router=useRouter()
const encounters=ref<EncounterRecord[]>(loadEncounters())
const characters=ref<CharacterRecord[]>(loadCharacters().filter(character=>!character.draft))
const encounterId=computed(()=>String(route.params.id||''))
const encounter=computed(()=>encounters.value.find(item=>item.id===encounterId.value)||null)
const character=computed(()=>encounter.value?characters.value.find(item=>item.id===encounter.value?.characterId)||null:null)
function stamp(){return new Date().toISOString()}
function persist(){writeEncounters(encounters.value)}
function attribute(key:'agility'|'might'|'hide'|'lore'|'bravery'){return Number(character.value?.attributes?.[key]||0)}
const secondaryStats=computed(()=>({speed:2+attribute('agility'),aim:attribute('agility')*2,mettle:attribute('might')*2,ward:attribute('hide')*2,control:attribute('lore')*2,power:attribute('might'),guts:attribute('hide')}))
const magicLevel=computed(()=>character.value?.path==='magic'?1:0)
const manaRegen=computed(()=>2+magicLevel.value)
const skillEntries=computed(()=>Object.entries(character.value?.skillRanks||{}).sort(([a],[b])=>a.localeCompare(b)))
const characterSpells=computed(()=>{const c=character.value;if(!c)return[];const signature=c.loreAttunement?loreSpells[c.loreAttunement]?.[0]:'';return Array.from(new Set([signature,...(c.spells||[]),...(c.invocationSpells||[]),c.invocationSpell||''].filter(Boolean) as string[]))})
function skillModifier(rank:number){return Number(rank||0)*2}
function addEvent(text:string){const item=encounter.value;if(!item)return;item.events=[`${new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})} — ${text}`,...item.events].slice(0,40);item.lastResult=text;item.updatedAt=stamp();persist()}
const encounterHealth=computed({get:()=>encounter.value?.health??30,set:(value:number)=>{const item=encounter.value;if(!item)return;const before=item.health;item.health=Math.max(0,Number(value||0));if(before<=0&&item.health>0)item.fateMarks=0;item.updatedAt=stamp();persist()}})
const encounterFateMarks=computed({get:()=>encounter.value?.fateMarks??0,set:(value:number)=>{const item=encounter.value;if(!item)return;item.fateMarks=Math.max(0,Math.min(3,Number(value||0)));item.updatedAt=stamp();persist()}})
const encounterMana=computed({get:()=>encounter.value?.mana??0,set:(value:number)=>{const item=encounter.value;if(!item)return;item.mana=Math.max(0,Number(value||0));item.updatedAt=stamp();persist()}})
function changeRound(delta:number){const item=encounter.value;if(!item)return;const before=item.round;item.round=Math.max(1,item.round+delta);if(item.round>before){item.mana+=manaRegen.value;addEvent(`Round ${item.round}: +${manaRegen.value} Mana restored at the start of the round.`)}else{item.updatedAt=stamp();persist()}resetRoundAbilities()}
function completeEncounter(){const item=encounter.value;if(!item)return;item.status='completed';item.updatedAt=stamp();persist()}
function reopenEncounter(){const item=encounter.value;if(!item)return;item.status='ongoing';item.updatedAt=stamp();persist()}
function deleteEncounter(){const item=encounter.value;if(!item||!confirm('Delete this encounter and its local history?'))return;encounters.value=encounters.value.filter(entry=>entry.id!==item.id);persist();void router.push('/simulator')}

const abilitySpent=reactive({instinct:false,movement:false,combat:false,reaction:false})
const abilityTypes=['instinct','movement','combat','reaction'] as const
const abilityRemaining=computed(()=>abilityTypes.filter(type=>!abilitySpent[type]))
function resetRoundAbilities(){abilityTypes.forEach(type=>abilitySpent[type]=false)}
function toggleAbility(type:(typeof abilityTypes)[number]){abilitySpent[type]=!abilitySpent[type]}
const abilityStatus=computed(()=>abilityRemaining.value.length===0?'No Root ability types remain this round. Passive Abilities may still apply when their trigger and restrictions are met.':abilityRemaining.value.length===4?'Round ready: all four Root ability types are available.':`${abilityRemaining.value.length} Root ability type${abilityRemaining.value.length===1?'':'s'} remaining this round.`)

function die(){const a=new Uint32Array(1);crypto.getRandomValues(a);return(a[0]%10)+1}
function dice(count:number){return Array.from({length:count},die)}
const strikeTypes:StrikeType[]=['melee','ranged','magical']
const strikeType=ref<StrikeType>('melee'),strikeCond=ref(0),wardCond=ref(0)
const strikeStatValue=computed(()=>strikeType.value==='melee'?secondaryStats.value.mettle:strikeType.value==='ranged'?secondaryStats.value.aim:secondaryStats.value.control)
const wardStatValue=computed(()=>secondaryStats.value.ward)
const strikeStatLabel=computed(()=>strikeType.value==='melee'?'Mettle':strikeType.value==='ranged'?'Aim':'Control')
const combatResult=ref<ReturnType<typeof opposedResult>|null>(null)
function rollCombat(){combatResult.value=opposedResult(dice(3),strikeStatValue.value,strikeCond.value,dice(3),wardStatValue.value,wardCond.value);abilitySpent.combat=true;addEvent(`${strikeType.value[0].toUpperCase()+strikeType.value.slice(1)} ${combatResult.value.hit?'Hit':'Miss'} — Strike ${combatResult.value.strike.total}, Ward ${combatResult.value.ward.total}`)}

const damage=ref(8),damageType=ref<'standard'|'direct'|'lethal'>('standard'),equipment=ref(0),damageCond=ref(0),resistance=ref(0),weakness=ref(0)
const netDamageConditions=computed(()=>Number(damageCond.value||0)+Math.abs(Number(resistance.value||0))-Math.abs(Number(weakness.value||0)))
const damageCalc=computed(()=>damageResult(damage.value,damageType.value,attribute('hide'),equipment.value,netDamageConditions.value))
function applyDamage(){if(!encounter.value)return;encounterHealth.value=Math.max(0,encounterHealth.value-damageCalc.value.suffered);addEvent(`${damageCalc.value.suffered} ${damageType.value} damage suffered; Health ${encounterHealth.value}.`)}
const hallows=ref<number|null>(null)
function rollHallows(){hallows.value=die();if(hallows.value>=6)addEvent(`Hallows ${hallows.value}: pass.`);else{encounterFateMarks.value=Math.min(3,encounterFateMarks.value+1);addEvent(`Hallows ${hallows.value}: fail; Fate Mark ${encounterFateMarks.value}/3.`)}}
const healthPenaltyValue=computed(()=>healthPenalty(encounterHealth.value))

const spellName=ref(''),spellBaseCostManual=ref(0),spellAdjustment=ref(0)
const selectedSpellDetail=computed(()=>spellName.value?spellDetails[spellName.value]:undefined)
const selectedSpellBaseCost=computed(()=>selectedSpellDetail.value?.manaCost===null||selectedSpellDetail.value?.manaCost===undefined?Number(spellBaseCostManual.value||0):Number(selectedSpellDetail.value.manaCost))
const selectedSpellAttuned=computed(()=>Boolean(character.value?.loreAttunement&&selectedSpellDetail.value?.lore===character.value.loreAttunement))
const spellEffectiveCost=computed(()=>Math.max(0,selectedSpellBaseCost.value-(selectedSpellAttuned.value?2:0)+Number(spellAdjustment.value||0)))
function recordSpell(){if(!encounter.value||!spellName.value.trim())return;if(spellEffectiveCost.value>encounterMana.value){alert('The encounter does not have enough Mana for this cost.');return}encounterMana.value-=spellEffectiveCost.value;addEvent(`Cast ${spellName.value.trim()} for ${spellEffectiveCost.value} Mana; ${encounterMana.value} Mana remaining.`)}
</script>

<template>
  <main class="page encounter-page">
    <AppHeader compact back-to="/simulator" back-label="Back to Rhythm Engine" prefer-back-to />
    <template v-if="encounter && character">
      <nav class="rule-breadcrumb encounter-back-link"><RouterLink to="/simulator">Rhythm Engine</RouterLink><span>›</span><strong>Combat Encounter</strong></nav>
      <div class="page-title-block encounter-page-heading"><div><p class="eyebrow">COMBAT ENCOUNTER</p><h1>{{ encounter.name }}</h1><p>{{ character.name }} · {{ character.species }}<template v-if="character.campaignName"> · {{ character.campaignName }}</template></p></div><div class="round-control"><button type="button" class="icon-button" @click="changeRound(-1)">−</button><span><small>ROUND</small><strong>{{ encounter.round }}</strong></span><button type="button" class="icon-button" @click="changeRound(1)">+</button></div></div>

      <section class="character-encounter-panel card-surface"><div class="character-encounter-heading"><div><span class="eyebrow">CHARACTER</span><h3>{{ character.name }}</h3><small>{{ character.species }} · {{ character.homeland }}</small></div><span class="value-chip">{{ character.path==='magic'?'Magic Level 1':'Talent Path' }}</span></div><div class="secondary-stat-grid"><div><span>Speed</span><strong>{{ secondaryStats.speed }}</strong></div><div><span>Aim</span><strong>{{ secondaryStats.aim }}</strong></div><div><span>Mettle</span><strong>{{ secondaryStats.mettle }}</strong></div><div><span>Ward</span><strong>{{ secondaryStats.ward }}</strong></div><div><span>Control</span><strong>{{ secondaryStats.control }}</strong></div><div><span>Power</span><strong>{{ secondaryStats.power }}</strong></div><div><span>Guts</span><strong>{{ secondaryStats.guts }}</strong></div></div><details v-if="skillEntries.length" class="encounter-character-detail"><summary>Skills</summary><div class="detail-list"><p v-for="([skill,rank]) in skillEntries" :key="skill"><strong>{{ skill }}</strong> · Rank {{ rank }} · Modifier +{{ skillModifier(rank) }}</p></div></details><details v-if="character.talents?.length" class="encounter-character-detail"><summary>Talents</summary><div class="detail-list"><p v-for="talent in character.talents" :key="talent">{{ talent }}</p></div></details><details v-if="character.path==='magic'" class="encounter-character-detail"><summary>Magic</summary><div class="detail-list"><p><strong>Lore:</strong> {{ character.loreAttunement||'—' }}</p><p><strong>Mana restored each round:</strong> {{ manaRegen }}</p><p v-for="spell in characterSpells" :key="spell">{{ spell }}</p></div></details></section>

      <div class="encounter-vital-grid"><label><span>Health</span><input v-model.number="encounterHealth" class="field-control" type="number" min="0" max="30" /></label><label><span>Mana</span><input v-model.number="encounterMana" class="field-control" type="number" min="0" /></label><label><span>Fate Marks</span><input v-model.number="encounterFateMarks" class="field-control" type="number" min="0" max="3" /></label></div>

      <div class="active-encounter-tools">
        <details class="encounter-tool-panel abilities-panel" open><summary>Abilities</summary><div class="encounter-tool-body"><p class="ability-help">Resolve start-of-turn triggers first. Root limits track one Instinct, Movement, Combat, and Reaction use per type each round; Passive Abilities apply when their own triggers and restrictions are met.</p><div class="ability-root-grid"><button v-for="type in abilityTypes" :key="type" type="button" :class="{spent:abilitySpent[type]}" @click="toggleAbility(type)"><span>Root {{ type }}</span><strong>{{ abilitySpent[type]?'Used':'Available' }}</strong></button><article class="passive-ability-card"><span>Passive</span><strong>Trigger Based</strong><small>Does not consume a Root type.</small></article></div><div class="ability-status" :class="{empty:abilityRemaining.length===0}">{{ abilityStatus }}</div><button class="secondary-button wide" @click="resetRoundAbilities">Reset Round Abilities</button></div></details>

        <details class="encounter-tool-panel" open><summary>Attacking &amp; Defending</summary><div class="encounter-tool-body"><div class="strike-type-tabs"><button v-for="type in strikeTypes" :key="type" :class="{active:strikeType===type}" @click="strikeType=type">{{ type[0].toUpperCase()+type.slice(1) }} Strike</button></div><div class="field-grid two"><label><span>{{ strikeStatLabel }} — Strike Stat</span><div class="field-control stat-readout">{{ strikeStatValue }}</div></label><label><span>Strike Conditions</span><input v-model.number="strikeCond" class="field-control" type="number" /></label><label><span>Ward — Defence Stat</span><div class="field-control stat-readout">{{ wardStatValue }}</div></label><label><span>Ward Conditions</span><input v-model.number="wardCond" class="field-control" type="number" /></label></div><button class="primary-button wide" @click="rollCombat">Roll {{ strikeType[0].toUpperCase()+strikeType.slice(1) }} Strike &amp; Ward</button><div v-if="combatResult" class="versus-grid"><div><span>STRIKE</span><strong>{{ combatResult.strike.total }}</strong><small>{{ combatResult.strike.rolled.join(' + ') }}</small></div><div class="vs">VS</div><div><span>WARD</span><strong>{{ combatResult.ward.total }}</strong><small>{{ combatResult.ward.rolled.join(' + ') }}</small></div></div><div v-if="combatResult" class="notice" :class="combatResult.hit?'good':'bad'">{{ combatResult.hit?'HIT — Strike exceeded Ward.':'MISS — Ward wins ties and higher results.' }}</div></div></details>

        <details class="encounter-tool-panel" open><summary>Spells &amp; Mana</summary><div class="encounter-tool-body"><div class="field-grid two"><label><span>Spell</span><select v-model="spellName" class="field-control"><option value="">Choose a Spell</option><option v-for="spell in characterSpells" :key="spell" :value="spell">{{ spell }}</option></select></label><label><span>Base Mana Cost</span><input v-model.number="spellBaseCostManual" class="field-control" type="number" min="0" :disabled="selectedSpellDetail?.manaCost!==null&&selectedSpellDetail?.manaCost!==undefined" /></label><label><span>Attunement</span><div class="field-control stat-readout">{{ selectedSpellAttuned?'−2 Mana':'No reduction' }}</div></label><label><span>Other Mana Adjustment</span><input v-model.number="spellAdjustment" class="field-control" type="number" /></label></div><article v-if="selectedSpellDetail" class="spell-encounter-card"><div><span>{{ selectedSpellDetail.lore }}</span><strong>{{ spellName }}</strong><b v-if="selectedSpellDetail.manaCost!==null">{{ spellEffectiveCost }} Mana</b></div><p>{{ selectedSpellDetail.flavor }}</p></article><div class="sim-stat-total"><span>Recorded Mana Cost</span><strong>{{ spellEffectiveCost }}</strong><small>{{ encounterMana }} available · {{ manaRegen }} restored/round</small></div><button class="secondary-button wide" :disabled="!spellName||spellEffectiveCost>encounterMana" @click="recordSpell">Record Spell Use</button></div></details>

        <details class="encounter-tool-panel"><summary>Damage &amp; Guts</summary><div class="encounter-tool-body"><div class="field-grid three"><label><span>Incoming Damage</span><input v-model.number="damage" class="field-control" type="number" min="0" /></label><label><span>Damage Type</span><select v-model="damageType" class="field-control"><option value="standard">Standard</option><option value="direct">Direct</option><option value="lethal">Lethal</option></select></label><label><span>Hide / Base Guts</span><div class="field-control stat-readout">{{ attribute('hide') }}</div></label><label><span>Equipment Guts</span><input v-model.number="equipment" class="field-control" type="number" min="0" /></label><label><span>Conditions</span><input v-model.number="damageCond" class="field-control" type="number" /></label><label><span>Resistance</span><input v-model.number="resistance" class="field-control" type="number" min="0" /></label><label><span>Weakness</span><input v-model.number="weakness" class="field-control" type="number" min="0" /></label></div><p class="damage-rule-note">Resistance adds a positive Guts Condition and Weakness adds a negative Guts Condition after the damage category modifies Guts.</p><div class="metric-grid"><div><span>Effective Guts</span><strong>{{ damageCalc.guts }}</strong></div><div><span>Damage Suffered</span><strong>{{ damageCalc.suffered }}</strong></div></div><button class="secondary-button wide" @click="applyDamage">Apply Damage</button></div></details>

        <details class="encounter-tool-panel"><summary>Health, Hallows &amp; Fate Marks</summary><div class="encounter-tool-body"><div class="metric-grid"><div><span>Health Penalty</span><strong>{{ healthPenaltyValue===null?'Defeated':healthPenaltyValue }}</strong></div><div><span>Fate Marks</span><strong>{{ encounterFateMarks }} / 3</strong></div></div><button class="secondary-button wide" @click="rollHallows">Roll 1d10 Hallows Save</button><div v-if="hallows!==null" class="notice" :class="hallows>=6?'good':'bad'">{{ hallows>=6?`PASS — ${hallows}`:`FAIL — ${hallows}; Fate Mark ${encounterFateMarks}/3.` }}</div></div></details>
        <details v-if="encounter.events.length" class="encounter-tool-panel"><summary>Encounter Log</summary><div class="encounter-log"><p v-for="(event,index) in encounter.events" :key="index">{{ event }}</p></div></details>
      </div>
      <div class="encounter-page-actions"><button v-if="encounter.status==='ongoing'" class="secondary-button" @click="completeEncounter">Complete Encounter</button><button v-else class="secondary-button" @click="reopenEncounter">Reopen Encounter</button><button class="danger-button" @click="deleteEncounter">Delete Encounter</button></div>
    </template>
    <section v-else class="empty-state card-surface"><h2>Encounter Not Found</h2><p>The encounter or its saved character is not available on this device.</p><RouterLink class="primary-button" to="/simulator">Back to Rhythm Engine</RouterLink></section>
  </main>
</template>

<style scoped>
.rule-breadcrumb{display:flex;gap:7px;align-items:center;color:var(--ink-soft)}.rule-breadcrumb a{color:var(--accent-dark);font-weight:800;text-decoration:none}.round-control{display:grid;grid-template-columns:36px 60px 36px;align-items:center;gap:4px}.round-control>span{text-align:center}.round-control small{display:block;font-size:8px}.round-control strong{font-size:20px}.character-encounter-panel{display:grid;gap:10px;padding:12px;border:1px solid var(--line);border-top:5px solid var(--accent);border-radius:10px;background:var(--paper)}.character-encounter-heading{display:flex;justify-content:space-between;gap:12px}.character-encounter-heading h3{margin:0;font-family:Georgia,'Times New Roman',serif}.character-encounter-heading small{color:var(--ink-soft)}.secondary-stat-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.secondary-stat-grid>div{display:grid;justify-items:center;gap:2px;padding:8px 5px;border:1px solid var(--line);border-radius:8px;background:var(--paper-2)}.secondary-stat-grid span{color:var(--ink-soft);font-size:calc(8px + var(--font-offset));font-weight:800}.encounter-character-detail{border-top:1px solid var(--line);padding-top:7px}.encounter-character-detail summary{font-weight:850;cursor:pointer}.detail-list{padding:5px 2px}.detail-list p{margin:4px 0;color:var(--ink-soft)}.encounter-vital-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:12px 0}.encounter-vital-grid label>span{display:block;margin-bottom:4px;font-weight:850}.active-encounter-tools{display:grid;gap:9px}.encounter-tool-panel{border:1px solid var(--line);border-radius:10px;background:var(--paper-2);overflow:hidden}.encounter-tool-panel summary{padding:10px 12px;font-weight:850;cursor:pointer;background:color-mix(in srgb,var(--paper-2) 78%,var(--accent-wash))}.encounter-tool-body{padding:11px}.abilities-panel{border-top:5px solid #5b7440}.ability-help{margin:0 0 10px;color:var(--ink-soft);line-height:1.45}.ability-root-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.ability-root-grid button,.passive-ability-card{min-height:68px;display:grid;align-content:center;justify-items:center;gap:3px;padding:7px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);text-transform:capitalize}.ability-root-grid button.spent{opacity:.58;text-decoration:line-through}.passive-ability-card small{color:var(--ink-soft);text-align:center}.ability-status{margin:9px 0;padding:8px 10px;border-radius:8px;background:color-mix(in srgb,var(--accent-wash) 42%,var(--paper));font-weight:750}.ability-status.empty{color:var(--danger)}.strike-type-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:9px}.strike-type-tabs button{min-height:35px;border:1px solid var(--line);border-radius:8px;background:var(--paper-2);color:var(--ink-soft);font-weight:800}.strike-type-tabs button.active{border-color:var(--accent);background:var(--accent-wash);color:var(--ink)}.stat-readout{display:flex;align-items:center;font-weight:850;background:var(--paper-2)}.spell-encounter-card{margin-top:9px;padding:10px 11px;border:1px solid var(--line);border-top:5px solid #76518e;border-radius:9px;background:var(--paper)}.spell-encounter-card>div{display:flex;align-items:baseline;justify-content:space-between;gap:10px}.spell-encounter-card p,.damage-rule-note{color:var(--ink-soft)}.encounter-log{max-height:260px;overflow:auto;padding:8px}.encounter-log p{margin:0;padding:6px 0;border-bottom:1px solid var(--line)}.encounter-page-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:12px}@media(max-width:760px){.secondary-stat-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.ability-root-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.passive-ability-card{grid-column:1/-1}.encounter-page-heading{align-items:flex-start!important;flex-direction:column}.encounter-vital-grid{grid-template-columns:1fr}.encounter-page-actions{display:grid;grid-template-columns:1fr}}
</style>
